     * 查询某测量键的全部版本（按版本号升序）。
     */
    public List<Measurement> findRevisions(String key) {
        return jdbc.query(
                "SELECT " + COLUMNS + " FROM measurement WHERE measurement_key = ? ORDER BY revision",
                MAPPER, key);
    }

