            Integer releaseCount = jdbc.queryForObject(
                    "SELECT COUNT(*) FROM release_record rr "
                            + "JOIN measurement m ON m.id = rr.measurement_id "
                            + "WHERE m.measurement_key = ?",
                    Integer.class, "W-C%d".formatted(r));
